seq = open("region.fasta").read()
lines = seq.strip().split("\n")
sequence = "".join(lines[1:]).upper()

comp = {'A':'T','T':'A','G':'C','C':'G','N':'N'}
def rc(s): return "".join(comp[b] for b in reversed(s))

stop_cods = {'TAA','TAG','TGA'}

def orfs(seq, strand_name):
    results = []
    for frame in range(3):
        i = frame
        start = None
        while i < len(seq)-2:
            codon = seq[i:i+3]
            if len(codon) < 3:
                break
            if start is None:
                if codon in ('ATG','GTG','TTG'):
                    start = i
            else:
                if codon in stop_cods:
                    length = i+3-start
                    if length >= 200:
                        # check internal stops for non-ATG starts ambiguity: none by construction
                        results.append((start+1, i+3, (i+3-start)//3, seq[start:start+3], strand_name, frame+1))
                    start = None
            i += 3
    return results

def orfs_rev(seq, strand_name):
    r = rc(seq)
    res = []
    for (s,e,l,st,f) in orfs(r, strand_name):
        # convert reverse coords to forward strand coordinates
        end_f = len(seq) - s + 1
        beg_f = len(seq) - e + 1
        res.append((beg_f, end_f, l, st, f))
    return res

all_orfs = orfs(sequence, "+") + orfs_rev(sequence, "-")
all_orfs.sort(key=lambda x: -x[2])
for o in all_orfs[:20]:
    print(o)
