                    if length_nt >= 200:
                        results.append((start+1, i+3, length_nt, s[start:start+3], strand_name, frame+1))
                    start = None
            i += 3
    return results

def orfs_r(seq):
    r = rc(seq)
    res = []
    for (s,e,l,st,name,frame) in orfs_f(r, "-"):
        end_f = len(seq) - s + 1   # start codon on rev comp maps to this fwd coord (end)
        beg_f = len(seq) - e + 1
        res.append((beg_f, end_f, l, st, frame))
    return res

all_orfs = orfs_f(sequence, "+") + orfs_r(sequence)
