def sd_score(sub):
    ideal = "AGGAGG"
    score = 0
    for a,b in zip(sub, ideal):
        if a=='A' and b=='A': score+=3
        elif a=='G' and b=='G': score+=3
        elif a=='G' and b=='A': score+=1
        else: pass
    return score

print("Upstream context of ORF start (951-1160):")
