print()

best=[]
for pos in range(1101, 1161):
    w = sequence[pos:pos+6]
    sc = sd_score(w)
    if sc >= 5:
        best.append((pos+1, pos+7, w, sc))
print("Candidate Shine-Dalgarno hits (score>=5) upstream of ATG at 1161:")
for b in best: print(b)
print()

