seq = open("region.fasta").read()
lines = seq.strip().split("\n")
S = "".join(lines[1:]).upper()

# direct repeats: identical 12-mers occurring >=2 times
n=len(S)
from collections import defaultdict
d = defaultdict(list)
for i in range(n-11):
    d[S[i:i+12]].append(i+1)
dups = {k:v for k,v in d.items() if len(v)>1}
print("12-mer direct repeats found:", len(dups))
for k,v in list(dups.items())[:20]:
    print(k, v)
print()
# hairpin: inverted repeats, 6-mer stems spaced <= 14
comp = {'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return "".join(comp[b] for b in reversed(s))
hair = []
for i in range(n-12):
    stem = S[i:i+6]
    # look downstream up to 14 nt spacer
    for j in range(i+7, min(i+7+14, n-6)):
        if S[j:j+6] == rc(stem):
            hair.append((i+1, j+1, j-i-6, stem, S[j:j+6]))
print("Potential hairpin stems (6bp, spacer<=14):", len(hair))
for h in hair[:20]:
    print(h)
